// ── Position calc ──────────────────────────────────────────────────────────────

const PW = 300;
const PM = 10;

function calcPos(rect: DOMRect): { top: number; left: number } {
  const ww = window.innerWidth;
  const wh = window.innerHeight;
  const ph = 310; // approx preview height

  // On very small screens, center horizontally
  if (ww < 500) {
    const left = Math.max(8, (ww - PW) / 2);
    const top  = Math.max(8, Math.min(rect.bottom + 8, wh - ph - 8));
    return { top, left };
  }

  // Prefer right side, fall back to left
  let left = rect.right + PM;
  if (left + PW > ww - 8) left = rect.left - PW - PM;
  left = Math.max(8, Math.min(left, ww - PW - 8));

  // Center vertically on card
  let top = rect.top + rect.height / 2 - ph / 2;
  top = Math.max(8, Math.min(top, wh - ph - 8));

  return { top, left };
}

// ── Preview portal ─────────────────────────────────────────────────────────────

interface PreviewProps {
  item: MediaItem;
  rect: DOMRect;
  onOpen: () => void;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
  withBackdrop: boolean; // true when touch-triggered
  onBackdropTap: () => void;
}

function Preview({ item, rect, onOpen, onMouseEnter, onMouseLeave, withBackdrop, onBackdropTap }: PreviewProps) {
  const pos      = calcPos(rect);
  const title    = mediaTitle(item);
  const year     = mediaYear(item);
  const backdrop = backdropUrl(item.backdrop_path, 'w780');

  return ReactDOM.createPortal(
    <>
      {/* Transparent backdrop for touch-dismiss */}
      {withBackdrop && (
        <div
          style={{ position: 'fixed', inset: 0, zIndex: 9998 }}
          onClick={onBackdropTap}
        />
      )}
      <PreviewWrap
        top={pos.top}
        left={pos.left}
        onMouseEnter={onMouseEnter}
        onMouseLeave={onMouseLeave}
      >
        {backdrop
          ? <PreviewBackdrop src={backdrop} />
          : <PreviewBackdropEmpty />
        }
        <PreviewBody>
          <PreviewTitle>{title}</PreviewTitle>
          <PreviewMeta>
            <PreviewRating><Star size={11} fill="currentColor" />{item.vote_average.toFixed(1)}</PreviewRating>
            {year && <PreviewYear>{year}</PreviewYear>}
            <PreviewKind kind={item.media_type}>
              {item.media_type === 'movie' ? 'Film' : 'TV'}
            </PreviewKind>
          </PreviewMeta>
          {item.overview && <PreviewOverview>{item.overview}</PreviewOverview>}
          <PreviewBtn onClick={onOpen}>
            <Info size={13} />
            More Info
          </PreviewBtn>
        </PreviewBody>
      </PreviewWrap>
    </>,
    document.body,
  );
}

// ── MediaCard ─────────────────────────────────────────────────────────────────

interface Props {
  item: MediaItem;
  onClick: (item: MediaItem) => void;
}

export function MediaCard({ item, onClick }: Props) {
  const title  = mediaTitle(item);
  const year   = mediaYear(item);
  const poster = posterUrl(item.poster_path);

  const cardRef      = useRef<HTMLDivElement>(null);
  const hoverTimer   = useRef<ReturnType<typeof setTimeout>>();
  const leaveTimer   = useRef<ReturnType<typeof setTimeout>>();

  const [hovered,     setHovered]     = useState(false);
  const [showPreview, setShowPreview] = useState(false);
  const [previewRect, setPreviewRect] = useState<DOMRect | null>(null);
  const [touchMode,   setTouchMode]   = useState(false);  // preview opened by touch

  useEffect(() => () => {
    clearTimeout(hoverTimer.current);
    clearTimeout(leaveTimer.current);
  }, []);

  const openPreview = useCallback((rect: DOMRect, touch: boolean) => {
    setPreviewRect(rect);
    setShowPreview(true);
    setTouchMode(touch);
  }, []);

  const closePreview = useCallback(() => {
    setShowPreview(false);
    setPreviewRect(null);
    setTouchMode(false);
  }, []);

  const handleOpen = useCallback(() => {
    closePreview();
    onClick(item);
  }, [item, onClick, closePreview]);

  // ── Desktop mouse events ──────────────────────────────────────────────────

  const handleMouseEnter = useCallback(() => {
    setHovered(true);
    clearTimeout(leaveTimer.current);
    hoverTimer.current = setTimeout(() => {
      const rect = cardRef.current?.getBoundingClientRect();
      if (rect) openPreview(rect, false);
    }, 400);
  }, [openPreview]);

  const handleMouseLeave = useCallback(() => {
    setHovered(false);
    clearTimeout(hoverTimer.current);
    // Delay close so mouse can travel to preview
    leaveTimer.current = setTimeout(closePreview, 180);
  }, [closePreview]);

  const handlePreviewMouseEnter = useCallback(() => {
    clearTimeout(leaveTimer.current);
  }, []);

  const handlePreviewMouseLeave = useCallback(() => {
    closePreview();
  }, [closePreview]);

  // ── Touch events (iPad / mobile) ──────────────────────────────────────────

  const handleTouchStart = useCallback((e: React.TouchEvent) => {
    if (showPreview) return; // let touch propagate to preview buttons

    // On very small screens skip preview, go straight to detail
    if (window.innerWidth < 360) {
      onClick(item);
      return;
    }

    e.preventDefault(); // suppress synthetic click that would fire immediately
    const rect = cardRef.current?.getBoundingClientRect();
    if (rect) openPreview(rect, true);
  }, [showPreview, item, onClick, openPreview]);

  // Click fires on desktop after mouse hover (no preview yet) or second tap
  const handleClick = useCallback(() => {
    if (!showPreview && !touchMode) {
      handleOpen();
    }
  }, [showPreview, touchMode, handleOpen]);

  return (
    <>
      <Card
        ref={cardRef}
        onClick={handleClick}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onTouchStart={handleTouchStart}
        title={title}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') handleOpen(); }}
      >
        <TypeTag kind={item.media_type}>
          {item.media_type === 'movie' ? 'Film' : 'TV'}
        </TypeTag>
        {poster
          ? <PosterImg src={poster} alt={title} loading="lazy" />
          : (
            <PosterPlaceholder>
              🎬
              <PlaceholderTitle>{title}</PlaceholderTitle>
            </PosterPlaceholder>
          )
        }
        <Overlay visible={hovered}>
          <CardTitle>{title}</CardTitle>
          <CardMeta>
            <CardRating><Star size={9} fill="currentColor" />{item.vote_average.toFixed(1)}</CardRating>
            {year && <CardYear>{year}</CardYear>}
          </CardMeta>
        </Overlay>
      </Card>

      {showPreview && previewRect && (
        <Preview
          item={item}
          rect={previewRect}
          onOpen={handleOpen}
          onMouseEnter={handlePreviewMouseEnter}
          onMouseLeave={handlePreviewMouseLeave}
          withBackdrop={touchMode}
          onBackdropTap={closePreview}
        />
      )}
    </>
  );
}
