import type { MediaItem } from './tmdb';

const KEY_FAVORITES = 'atlantis:movies:favorites';
const KEY_SEEN = 'atlantis:movies:seen';
const SEEN_MAX = 15;

function load(key: string): MediaItem[] {
  try { return JSON.parse(localStorage.getItem(key) ?? '[]'); } catch { return []; }
}

function save(key: string, items: MediaItem[]): void {
  try { localStorage.setItem(key, JSON.stringify(items)); } catch {}
}

// ── Favorites ─────────────────────────────────────────────────────────────────

export function loadFavorites(): MediaItem[] {
  return load(KEY_FAVORITES);
}

export function isFavorite(item: MediaItem): boolean {
  return loadFavorites().some((f) => f.id === item.id && f.media_type === item.media_type);
}

export function toggleFavorite(item: MediaItem): MediaItem[] {
  const current = loadFavorites();
  const exists = current.some((f) => f.id === item.id && f.media_type === item.media_type);
  const next = exists
    ? current.filter((f) => !(f.id === item.id && f.media_type === item.media_type))
    : [item, ...current];
  save(KEY_FAVORITES, next);
  return next;
}

export function removeFavorite(item: MediaItem): MediaItem[] {
  const next = loadFavorites().filter(
    (f) => !(f.id === item.id && f.media_type === item.media_type),
  );
  save(KEY_FAVORITES, next);
  return next;
}

// ── Seen ──────────────────────────────────────────────────────────────────────

export function loadSeen(): MediaItem[] {
  return load(KEY_SEEN);
}

export function isSeen(item: MediaItem): boolean {
  return loadSeen().some((s) => s.id === item.id && s.media_type === item.media_type);
}

export function markSeen(item: MediaItem): MediaItem[] {
  const current = loadSeen().filter(
    (s) => !(s.id === item.id && s.media_type === item.media_type),
  );
  const next = [item, ...current].slice(0, SEEN_MAX);
  save(KEY_SEEN, next);
  return next;
}

export function removeSeen(item: MediaItem): MediaItem[] {
  const next = loadSeen().filter(
    (s) => !(s.id === item.id && s.media_type === item.media_type),
  );
  save(KEY_SEEN, next);
  return next;
}

export function toggleSeen(item: MediaItem): MediaItem[] {
  return isSeen(item) ? removeSeen(item) : markSeen(item);
}
